#!/usr/bin/env node
// Codemod: move finance master routes from flat dot-files into a master/ folder.
//   src/routes/_authenticated.finance.master-<x>.tsx
//   -> src/routes/_authenticated.finance.master.<x>.tsx
//
// Why this is safe:
// - The on-disk URL stays "/finance/master-<x>" only if dots are kept; moving
//   to a sub-segment changes the URL to "/finance/master/<x>". So this codemod
//   ALSO rewrites every `to="/finance/master-<x>"` Link / navigate / redirect
//   to the new path across src/. routeTree.gen.ts is regenerated by Vite.
//
// Usage:
//   node scripts/codemod-finance-master.mjs           # dry run
//   node scripts/codemod-finance-master.mjs --apply   # actually rename + edit
//
// After running, run `bun run build` (or restart dev) so routeTree.gen.ts
// regenerates, then run the smoke test:
//   E2E_ONLY=smoke_unknown_slug_404.py bun run tests/e2e/run_all.py
import { readdirSync, renameSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join } from "node:path";

const APPLY = process.argv.includes("--apply");
const ROUTES = "src/routes";
const PREFIX = "_authenticated.finance.master-";

const renames = readdirSync(ROUTES)
  .filter((f) => f.startsWith(PREFIX) && f.endsWith(".tsx"))
  .map((f) => {
    const slug = f.slice(PREFIX.length, -4); // e.g. "coa"
    const next = `_authenticated.finance.master.${slug}.tsx`;
    return {
      from: join(ROUTES, f),
      to: join(ROUTES, next),
      oldUrl: `/finance/master-${slug}`,
      newUrl: `/finance/master/${slug}`,
      oldRouteId: `/_authenticated/finance/master-${slug}`,
      newRouteId: `/_authenticated/finance/master/${slug}`,
    };
  });

console.log(`found ${renames.length} master routes`);
for (const r of renames) console.log(" •", r.oldUrl, "→", r.newUrl);

function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    const s = statSync(p);
    if (s.isDirectory()) {
      if (entry === "node_modules" || entry.startsWith(".")) continue;
      out.push(...walk(p));
    } else if (/\.(tsx?|jsx?|mts|cts)$/.test(entry)) {
      out.push(p);
    }
  }
  return out;
}

const files = walk("src");
let edits = 0;
for (const file of files) {
  let src = readFileSync(file, "utf8");
  let next = src;
  for (const r of renames) {
    // Rewrite Link to=, navigate({to:...}), and the createFileRoute id of the
    // moved file itself.
    next = next.split(`"${r.oldUrl}"`).join(`"${r.newUrl}"`);
    next = next.split(`'${r.oldUrl}'`).join(`'${r.newUrl}'`);
    next = next.split(`"${r.oldRouteId}"`).join(`"${r.newRouteId}"`);
  }
  if (next !== src) {
    edits++;
    if (APPLY) writeFileSync(file, next);
    console.log("edit", file);
  }
}

if (APPLY) {
  for (const r of renames) renameSync(r.from, r.to);
  console.log(`applied: renamed ${renames.length} files, edited ${edits}.`);
  console.log("now run a build so routeTree.gen.ts regenerates.");
} else {
  console.log(`\nDRY RUN — would rename ${renames.length} files and edit ${edits}.`);
  console.log("re-run with --apply to commit.");
}
